ai.format:
Szene des Physiklabors 2D (Baustein „Physiklabor“) — JSON. Die Engine ist fertig (starre Körper, Stösse, Reibung, Abprallen, Gelenke, Seile, Stangen, Federn, Rollen, Flüssigkeiten mit Druck und Auftrieb); die Szene sagt nur, WAS darin steht.
Einheiten: Meter, Kilogramm, Sekunden; y wächst nach oben, der Boden bei y = 0. Jede Zahl kann ein Ausdruck "=…" mit Werten sein, die in "vars" gezogen werden (z. B. "=4*tan(rad(kat))").

"world": { "gravity": 9.81, "air": 1 (Luftwiderstand, 0 — Vakuum), "depth": 0.1 (Dicke der Körper — daraus die Masse), "ground": true, "speed": 1 }
"vars": [{ "name": "kat", "from": 15, "to": 40, "step": 5 }] oder { "name": "ciecz", "pick": ["water", "oil"] } — jedes Mal anders; in Texten "{kat}"
"bodies": [{ "id", "label", "shape": "circle" (r) | "box" (w, h) | "poly" (points [[x,y],…], konvex), "x", "y", "angle" (Grad), "material", "density", "friction", "bounce", "static": true (unbeweglich), "vx", "vy", "spin", "drag": false (lässt sich nicht fassen), "trace": true (Spur), "color" }]
  Stoffe: {materials}
"joints": [{ "type": "pin" (Drehachse im Punkt "at"; mit "torque" und "speed" — ein Motor) | "rod" (Stange) | "rope" (Seil) | "spring" (Feder: "k" N/m, "damping") | "pulley" (Rolle: "a", "b", Räder bei "at" und "at2"), "a": id, "b": id (weggelassen — an der Welt befestigt), "on": [x, y] (Punkt auf "a", bezogen auf seine Mitte), "at": [x, y] (Punkt der Welt oder auf "b"), "length" }]
"fluids": [{ "id", "x", "y" (linke untere Ecke des Inneren), "w", "h", "wall", "layers": [{ "liquid", "height" }] (von unten; leichtere steigen von selbst auf), "holes": [{ "side": "left"|"right"|"bottom", "at" (Höhe über dem Boden), "size", "open" }] }] — Flüssigkeiten: {liquids}
"pipes": [{ "a", "b", "y", "size", "open" }] — ein Rohr, das zwei Behälter verbindet (verbundene Gefässe)
"show": { "vectors": [{vectors}] (v — Geschwindigkeit, g — Gewicht, lift — Auftrieb, net — resultierende Kraft), "trace": [id], "grid", "pressure" (Druck als Farbe der Tiefe), "values" (Massen, Kräfte) }
"graph": { "body": id, "of": [{graph}] } — ein Schreiber über der Zeit (h Höhe, v Geschwindigkeit, ek/ep/e Energien)
"allow": { "add": false, "palette": [{palette}], "tools": [{tools}], "edit", "drag" }
"controls": [{controls}] — Schalter der Welt im Feld
"goal": { "body": id, "area": [x0, y0, x1, y1], "for": 0.5, "say": "Geschafft!" } — ein Ziel (z. B. der Ball im Korb)
"steps": [{ "say": "…", "do": "play" | "pause" | { "open": idDesBehälters, "hole": 0 } | { "push": id, "vx": 2, "vy": 0 }, "wait": 3 }] — Schritte; „Zeigen“ führt sie der Reihe nach aus
"view": [x0, y0, x1, y1] — was am Anfang zu sehen ist
